"""Place value: drag digits into a place-value chart and see the number, its name in
words and its expanded form; round it on a number line.

The digit tiles (lblDigit, a control array) have DragMode = vpAutomatic, so pressing
the mouse on one drags it; the chart's places (lblPlace) get DragDrop with the tile as
Source. The number line is a Graph in number-line mode."""

from vp6 import *

PLACES = ("Millions", "Hundred thousands", "Ten thousands", "Thousands", "Hundreds", "Tens",
          "Ones")
ROUNDING = ("tens", "hundreds", "thousands", "ten thousands", "hundred thousands", "millions")

ONES = ("zero one two three four five six seven eight nine ten eleven twelve thirteen "
        "fourteen fifteen sixteen seventeen eighteen nineteen").split()
TENS = "_ _ twenty thirty forty fifty sixty seventy eighty ninety".split()
PERIODS = ("", "thousand", "million", "billion")


def below_thousand(n):
    words = []
    if n >= 100:
        words.append(f"{ONES[n // 100]} hundred")
        n %= 100
    if n >= 20:
        words.append(TENS[n // 10] + (f"-{ONES[n % 10]}" if n % 10 else ""))
    elif n:
        words.append(ONES[n])
    return " ".join(words)


def name_of(n):
    """A whole number in words: each period's number, then the period's name."""
    if n == 0:
        return "zero"
    parts, period = [], 0
    while n:
        n, group = divmod(n, 1000)
        if group:
            parts.append((below_thousand(group) + " " + PERIODS[period]).strip())
        period += 1
    return ", ".join(reversed(parts))


class Form1(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Place Value'
        self.Width = 680
        self.Height = 520
        self.lblIntro = Label(self,
                              Caption='Drag digits into the chart. Click a place to empty it.',
                              Left=16, Top=12, Width=640, Height=22, TabIndex=1)
        self.lblHead = ControlArray()
        self.lblHead[0] = Label(self, Caption='Millions', Left=16, Top=40, Width=88, Height=34,
                                Alignment=2, WordWrap=True, TabIndex=2)
        self.lblPlace = ControlArray()
        self.lblPlace[0] = Label(self, Caption='', Left=16, Top=78, Width=88, Height=52,
                                 Alignment=2, BorderStyle=1, FontSize=20, TabIndex=3,
                                 ToolTipText='Drop a digit here; click to empty it')
        self.lblDigit = ControlArray()
        self.lblDigit[0] = Label(self, Caption='0', Left=16, Top=148, Width=44, Height=40,
                                 Alignment=2, BorderStyle=1, FontSize=16, TabIndex=4,
                                 ToolTipText='Drag me into the chart', DragMode=1)
        self.cmdClear = CommandButton(self, Caption='&Clear', Left=540, Top=148, Width=116,
                                      Height=32, TabIndex=5)
        self.lblNumber = Label(self, Caption='', Left=16, Top=204, Width=640, Height=30,
                               FontSize=16, TabIndex=6)
        self.lblWords = Label(self, Caption='', Left=16, Top=238, Width=640, Height=40,
                              WordWrap=True, TabIndex=7)
        self.lblExpanded = Label(self, Caption='', Left=16, Top=280, Width=640, Height=40,
                                 WordWrap=True, TabIndex=8)
        self.lblRound = Label(self, Caption='Round to the nearest:', Left=16, Top=332, Width=150,
                              Height=24, TabIndex=9)
        self.cboRound = ComboBox(self, Style=2, Left=170, Top=328, Width=180, Height=26,
                                 TabIndex=10)
        self.lblRounded = Label(self, Caption='', Left=366, Top=332, Width=290, Height=24,
                                TabIndex=11)
        self.grfLine = Graph(self, Left=16, Top=364, Width=640, Height=110, Mode=1,
                             ShowNumbers=False, PanZoom=False, TabIndex=12)
    # endregion

    digits = [None] * len(PLACES)  # (each place's digit, None when empty)

    def Form_Load(self):
        self.digits = [None] * len(PLACES)
        for i in range(1, len(PLACES)):  # (the chart's other columns, like the first)
            head = Load(self.lblHead, i)
            head.Left = self.lblHead(0).Left + 92 * i
            head.Caption = PLACES[i]
            head.Visible = True
            place = Load(self.lblPlace, i)
            place.Left = self.lblPlace(0).Left + 92 * i
            place.Visible = True
        for digit in range(1, 10):
            tile = Load(self.lblDigit, digit)
            tile.Left = self.lblDigit(0).Left + 50 * digit
            tile.Caption = str(digit)
            tile.Visible = True
        for name in ROUNDING:
            self.cboRound.AddItem(name)
        self.cboRound.ListIndex = 1
        for place, digit in zip((3, 4, 5, 6), (4, 7, 0, 6)):  # (4,706 to start with)
            self.put(place, digit)

    def put(self, place, digit):
        self.digits[place] = digit
        self.lblPlace(place).Caption = "" if digit is None else str(digit)
        self.show_number()

    def lblPlace_DragDrop(self, Index, Source, X, Y):
        self.put(Index, Source.Index)  # (a digit tile's Index is its digit)

    def lblPlace_Click(self, Index):
        self.put(Index, None)

    def cmdClear_Click(self):
        for place in range(len(PLACES)):
            self.put(place, None)

    def number(self):
        """The chart's number: an empty place inside it counts as 0."""
        return sum((digit or 0) * 10 ** (len(PLACES) - 1 - place)
                   for place, digit in enumerate(self.digits))

    def show_number(self):
        n = self.number()
        if all(digit is None for digit in self.digits):
            self.lblNumber.Caption = "The number: (drag digits into the chart)"
            self.lblWords.Caption = self.lblExpanded.Caption = ""
        else:
            self.lblNumber.Caption = f"The number: {n:,}"
            self.lblWords.Caption = f"In words: {name_of(n)}"
            parts = [f"{digit * 10 ** (len(PLACES) - 1 - place):,}"
                     for place, digit in enumerate(self.digits) if digit]
            self.lblExpanded.Caption = "Expanded: " + (" + ".join(parts) or "0")
        self.show_rounding()

    def cboRound_Click(self):
        self.show_rounding()

    def show_rounding(self):
        """The number between the two it could round to, and the halfway mark."""
        if self.cboRound.ListIndex < 0:
            return
        n = self.number()
        step = 10 ** (self.cboRound.ListIndex + 1)
        low = n // step * step
        high = low + step
        half = low + step // 2
        rounded = high if n >= half else low
        self.lblRounded.Caption = f"{n:,} rounds to {rounded:,}"
        grf = self.grfLine
        grf.Clear()
        grf.Scale(low - step * 0.15, 1, high + step * 0.15, -1)
        grf.XStep = step / 10
        for end in (low, high):  # (the one it rounds to filled in, in green)
            grf.AddPoint(end, 0, Open=end != rounded, Label=f"{end:,}",
                         Color=RGB(46, 158, 68) if end == rounded else RGB(128, 128, 128))
        grf.AddPoint(half, 0, Open=True, Size=3, Color=RGB(128, 128, 128), Label="halfway")
        grf.AddPoint(n, 0, Color=vpRed, Label=f"{n:,}")


if __name__ == "__main__":
    run(Form1)
